-- Group legacy line-by-line poetry into native Verse blocks.
begin;
update public.human_archive_record_structures as target
set blocks = source.blocks
from (values
(131, $ha_verse$[{"id":"ha-131-verse-001","html":"<div class=\"ha-verse\"><div style=\"text-align:justify\">Am venit lângă tine și m-am așezat tăcut. Nu am zis nimic, doar un suspin despicat, mărunt. Drept frână, mi-am ațintit ochii într-un brad și-mi zburam mintea cu uratul de la gard la gard. Câte sunete să mai scot să mă primești vecine, străine? În surdine, te iubesc, cretine!</div><div style=\"text-align:justify\"></div><div style=\"text-align:justify\">Prea puține mi-au fost de folos din alfabet când limbile ni-s străine și buzele lipite cu aracet. Am înțeles, într-un final, că focul ni-e artificial și nu-i scânteie dintre cremeni cu același ideal. Nu facem foc, nu aducem lumină, n-avem căldură, doar ardem brazii din vină.</div><div style=\"text-align:justify\"></div><div style=\"text-align:justify\">Mă gândesc la tine! Te transpun în expresii. Cu privirea înspre brad, nu găsesc concesii să mai rămân o clipă lângă tine. Dar dincolo de brad, printre obsesii, mă găsesc pe mine într-o oglindă. Din spatele ei văd viața toată, cum pe cămila șerpuindă, colinzi din poartă în poartă.</div></div>","type":"verse"}]$ha_verse$::jsonb),
(137, $ha_verse$[{"id":"ha-137-verse-001","html":"<div class=\"ha-verse\"><div>Pădure, pe tine, cu sâmburi în sânge te aștept să crești</div><div>Cu gândul în păcat, vânez împăcat porumbeii cu vești</div><div>Un gol în mine scurmă înțelept maluri săpate adânci</div><div>După mâluri de plăcere, să mi se soarbă viața-ntre stânci.</p>\n</div><div>Am răsădit acolo, la tine un suflet cât o frunză</div><div>Dar toamna răstigni mirată tot ce-a rămas în urmă</div><div>A suflat peste pădure la fel cum clipești tu din gene</div><div>Romantică pictând cu depresie în acuarele.</div></div>","type":"verse"}]$ha_verse$::jsonb),
(141, $ha_verse$[{"id":"ha-141-verse-001","html":"<div class=\"ha-verse\"><div>Suntem un gând venit de sub pământ</div><div>Murdar și necuviincios</div><div>Cu picioarele unse cu soamală</div><div>I-am pășit pe umeri pe străbuni.</p>\n</div><div>Suntem un scrâșnet scos de un arbore bătrân</div><div>La o posibilă ultimă bătaie de vânt</div><div>Suntem un suspin al unui muribund</div><div>La prima atingere a unui sfânt.</p>\n</div><div>Suntem un omagiu al începuturilor târzii</div><div>Suntem suspansul unei nopți prea adânci pentru a mai fi zi</div><div>Suntem lumina din capul minerului uns cu mir</div><div>Îngropat în întunericul grămezii…</p>\n</div><div>Suntem o șoaptă sădită într-un mormânt</div><div>Un urlet fără de rost la lună</div><div>Ucigași înfometați ai serilor</div><div>Suntem stele sechestrare în privirea omului nebun.</p>\n</div><div>Suntem neamul proscris</div><div>Suntem fugitivi ai iadului</div><div>Suntem ceea ce vezi</div><div>O sferă în linii.</p>\n</div><div>Suntem timpul petrecut în treceri</div><div>Proiectat pe înțelesul limbii tale</div><div>Suntem o întâmplare</div><div>Un strop prelins pe geamul fortăreței tale.</p>\n</div><div>Suntem un corp fragil</div><div>Suntem o lumină rece</div><div>Un fenomen nepătruns de văz</div><div>Suntem un momen</div></div>","type":"verse"}]$ha_verse$::jsonb),
(3006, $ha_verse$[{"id":"ha-3006-verse-001","html":"<div class=\"ha-verse\"><div>I. GOLUL — Dincolo de somn</div><div><br></div><div>Gol...</div><div>în nocturnă</div><div>văd umbre</div><div>jucând un rol</div><div>pe scena unei vieți de om,</div><div>deprivat de somn,</div><div>adorm.</div><div><br></div><div>II. PERCEPȚIA — Când lumina prinde culoare</div><div><br></div><div>Culori se amăgesc între ele</div><div>că urma lor va naște pete și nuanțe:</div><div>de gri, de roșu, de alb, de negru,</div><div>de singurătate, de alinare, de căldură, de iubire.</div><div>În joacă le privesc,</div><div>în voia blândă a luminii.</div><div><br></div><div>Văd un joc universal,</div><div>un tango de ritual,</div><div>un du-te-vino neîncetat,</div><div>un strop de amor pe o buză de pahar,</div><div>ce coboară ușor pe piciorul de cristal,</div><div>pătând masa cu ireal.</div><div><br></div><div>III. DEZILUZIA — Dincolo de aparențe</div><div><br></div><div>Culori în subite transparențe</div><div>învârtesc noroiul lumii,</div><div>îl sculptează pe piedestal</div><div>și-l acoperă cu noaptea minții.</div><div><br></div><div>IV. UITAREA — Printre resturile existenței</div><div><br></div><div>Culori pe care nu le știm,</div><div>culori ascunse de dor,</div><div>culori uitate dinadins,</div><div>purtate la piept,</div><div>urcate pe-un nor,</div><div>rătăcite printr-un sertar,</div><div>printre baterii și imbusuri,</div><div>schițe și borcane</div><div>cu murături și ciorne</div><div>și un suflet fără gust.</div><div><br></div><div>Mă minunez, mă văd privindu-mă,</div><div>mă contemplu dincolo de limite,</div><div>neîncetat mă caut în colțurile minții;</div><div>epuizat, deconectez și sensul, și sfinții.</div><div><br></div><div>V. SFÂRȘITUL — Când viața se stinge</div><div><br></div><div>Culori în scântei tăcute</div><div>pictează-n frigul dimineții</div><div>cum se stinge o viață,</div><div>un amurg înmormântat sub munte.</div><div><br></div><div>Cu capul spre albia lumii,</div><div>unde îl plâng străbunii,</div><div>peste coroane împletite din zorii zilei</div><div>picură viață de dragul milei.</div><div><br></div><div>VI. PRAGUL — Între două lumi</div><div><br></div><div>Curat, îmbălsămat,</div><div>în alb înveșmântat,</div><div>pășește prin livadă, prin ochiuri de lumină,</div><div>și o briză caldă îi suspină</div><div>zâmbete dulci,</div><div>iubire prin rugi,</div><div>miros de pământ</div><div>și-un fior prin gând.</div><div><br></div><div>Acolo unde dragostea nu-i,</div><div>acolo unde zâmbete în culori diurne</div><div>atârnă în cui,</div><div>acolo unde respiră vânturi nocturne.</div><div><br></div><div>VII. GENEZA — Desprins din tot, născut din nimic</div><div><br></div><div>Acolo, în spațiul dintre lumi,</div><div>o amintire plânge printre cununi</div><div>apariția conștiinței</div><div>și decuparea ființei</div><div>din tot, din divin;</div><div>un observator</div><div>și un decor</div><div>străin de propriul creator.</div><div><br></div><div>Acolo prind formă și ființă:</div><div>un nimic cu voință</div><div>de a fi, de a nu muri,</div><div>de a mă naște și de a mă numi.</div><div><br></div><div>VIII. CĂLĂTORIA — În căutarea propriei ființe</div><div><br></div><div>Observator călător</div><div>pe sub pământ, prin zbor,</div><div>prin rafale de neștire,</div><div>până și lipsa uită să mă respire.</div><div><br></div><div>Culori născute din speranță,</div><div>un scâncet născut din neființă;</div><div>la unison, ființa-mi vibrează,</div><div>un semnal ascuns mă reîntrupează.</div><div><br></div><div>IX. RECUNOAȘTEREA — Într-o culoare, întregul</div><div><br></div><div>Îi decodific conștiința de pe mut,</div><div>îi dau sonor prin sufletul meu cărunt,</div><div>mă cobor în plecăciune și-i prezint respect.</div><div><br></div><div>Sunt o culoare refractată perfect.</div></div>","type":"verse"},{"id":"ha-3006-115","html":"<figure><img src=\"https://oeyxsqocldlovhsmzcjw.supabase.co/storage/v1/object/public/vha-post-media/3db54039-9208-4ec6-a741-94638e2ace16/e272294b-ab58-46ee-8100-2caee8462339-sunt-o-culoare.jpeg\" alt=\"\"></figure>","type":"image"}]$ha_verse$::jsonb)
) as source(record_id, blocks)
where target.record_id = source.record_id;
commit;
